function renderApexIcons(root = document) {
  // 1. Try Lucide CDN if available
  if (window.lucide && typeof window.lucide.createIcons === 'function') {
    try {
      window.lucide.createIcons({ root });
      return;
    } catch (e) {}
  }

  // 2. Fallback to embedded SVG icons
  const iconElements = root.querySelectorAll('i[data-lucide]');
  iconElements.forEach(el => {
    const iconName = el.getAttribute('data-lucide');
    const svgString = APEX_ICONS[iconName];
    if (svgString) {
      const wrapper = document.createElement('span');
      wrapper.innerHTML = svgString;
      const svg = wrapper.firstElementChild;
      
      // Preserve extra CSS classes
      const extraClasses = el.className.replace(/w-\S+|h-\S+/g, '').trim();
      if (extraClasses) svg.classList.add(...extraClasses.split(' ').filter(Boolean));
      
      el.parentNode.replaceChild(svg, el);
    }
  });
}

window.renderApexIcons = renderApexIcons;


