          { foodId: 'food_broccoli', name: 'Brócolos Cozidos ao Vapor', amount: 120, unit: 'g', calories: 42, protein: 2.9, carbs: 8.6, fat: 0.5, fiber: 4.0, sugar: 1.7, sodium: 48, potassium: 348, calcium: 48, iron: 0.8 }
